1	#!/usr/bin/env node
2	// The merge-to-main capture step (grow_with_claudinite pack): push this session's
3	// conversation onto the repo's orphan `conversation-logs` branch as one JSONL
4	// file named `<stamp>--issue-<n>--<session>.jsonl` (README.md owns the standard).
5	//
6	// Delta-aware: a session that merges more than once pushes a second, disjoint
7	// file holding only the entries after its previous capture — each file maps 1:1
8	// to a merge and its issue, so the nightly extract never re-reads a turn.
9	//
10	// All branch writes go through git plumbing (hash-object/mktree/commit-tree/push)
11	// against the fetched remote tip — the user's checkout and index are never
12	// touched, and there is no worktree to clean up.
13	//
14	// Usage (from the repo root, right after the merge lands):
15	//   node capture-log.mjs --issue <n> [--transcript <path>] [--branch <name>] [--session <id>]
16	//
17	// The session id (CLAUDE_CODE_SESSION_ID, or --session) names the transcript file
18	// exactly, so discovery searches every project directory for it — a remote/web
19	// session's transcript can land under a slug the git-root path never reproduces.
20	
21	import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
22	import { spawnSync } from 'node:child_process';
23	import { homedir } from 'node:os';
24	import { join, basename, dirname } from 'node:path';
25	import { pathToFileURL } from 'node:url';
26	
27	export const DEFAULT_BRANCH = 'conversation-logs';
28	
29	// --- pure helpers (exported for pack.test.mjs) -------------------------------
30	
31	// Split a transcript into { raw, entry } pairs, preserving the original line
32	// bytes — the capture must stay byte-faithful (re-encoding could reorder or
33	// reformat), so raw is what gets written and entry is only read for slicing.
34	// (engine/checks/helpers/session-transcript.mjs parseEntries returns parsed objects only, which is
35	// right for conversation rules but loses the fidelity capture needs.)
36	export function parseLines(text) {
37	  const out = [];
38	  for (const raw of (text || '').split('\n')) {
39	    if (!raw.trim()) continue;
40	    try { out.push({ raw, entry: JSON.parse(raw) }); } catch { /* partial trailing write — skip */ }
41	  }
42	  return out;
43	}
44	
45	// Merge the main transcript with any sidechain streams into one timestamp-ordered
46	// list. A timestampless entry (queue markers and the like) inherits its stream
47	// predecessor's timestamp so it stays glued to its neighbors through the merge.
48	export function bundleStreams(streams) {
49	  const tagged = [];
50	  streams.forEach((lines, s) => {
51	    let carry = '';
52	    lines.forEach((line, i) => {
53	      if (typeof line.entry.timestamp === 'string') carry = line.entry.timestamp;
54	      tagged.push({ raw: line.raw, entry: line.entry, ts: carry, s, i });
55	    });
56	  });
57	  return tagged
58	    .sort((a, b) => (a.ts < b.ts ? -1 : a.ts > b.ts ? 1 : a.s - b.s || a.i - b.i))
59	    .map(({ raw, entry, ts }) => ({ raw, entry, ts }));
60	}

